import java.util.HashSet;
import java.util.Set;

public class Main {
    public static void main(String[] args) {
        int[] a = {2, 5, 3, 5, 2};
        Set<Integer> seen = new HashSet<>();
        for (int n : a) {
            if (!seen.add(n)) {
                System.out.println(n);
                return;
            }
        }
        System.out.println(-1);
    }
}
